    /// Resolves GitHub asset URL for a specific target platform
    async fn resolve_github_asset_url_for_target(
        &self,
        tv: &ToolVersion,
        opts: &GitBackendOptions<'_>,
        repo: &str,
        version: &str,
        target: &PlatformTarget,
        asset_pattern: Option<&str>,
    ) -> Result<ReleaseAsset> {
        let api_url = opts.api_url();
        let release = self
            .get_github_release_for_url(&api_url, repo, version)
            .await?;
        let available_assets: Vec<String> = release.assets.iter().map(|a| a.name.clone()).collect();

        // Build asset list with URLs for checksum fetching
        let assets_with_urls: Vec<Asset> = release
            .assets
            .iter()
            .map(|a| Asset::new(&a.name, &a.browser_download_url))
            .collect();

        // Try explicit pattern first. `asset_pattern` replaces autodetection
        // entirely, so it intentionally takes precedence over and ignores
        // `matching`/`matching_regex` (there is no autodetected candidate set left
        // to narrow). Do NOT thread the matching filter into this branch.
        if let Some(pattern) = asset_pattern
            .map(str::to_string)
            .or_else(|| opts.asset_pattern_for_target(target))
        {
            // Template the pattern for the target platform
            let templated_pattern = template_string_for_target(&pattern, tv, target);

            let asset = self
                .pick_by_pattern(release.assets, &templated_pattern, |a| &a.name)
                .ok_or_else(|| {
                    eyre::eyre!(
                        "No matching asset found for pattern: {}\nAvailable assets: {}",
                        templated_pattern,
                        Self::format_asset_list(available_assets.iter())
                    )
                })?;

            // Try to get checksum from API digest or fetch from release assets
            let digest = if asset.digest.is_some() {
                asset.digest
            } else {
                self.try_fetch_checksum_from_assets(&assets_with_urls, &asset.name)
                    .await
            };

            return Ok(ReleaseAsset {
                name: asset.name,
                url: asset.browser_download_url,
                url_api: asset.url,
                digest,
            });
        }

        // Fall back to auto-detection for target platform
        let asset_name = asset_matcher::AssetMatcher::new()
            .for_target(target)
            .with_no_app(opts.no_app_for_target(target))
            .with_preferred_name(self.preferred_asset_name())
            .with_matching(opts.matching().unwrap_or_default())
            .with_matching_regex(opts.matching_regex().unwrap_or_default())
            .pick_from(&available_assets)?
            .name;
        let asset = self
            .find_asset_case_insensitive(&release.assets, &asset_name, |a| &a.name)
            .ok_or_else(|| {
                eyre::eyre!(
                    "Auto-detected asset not found: {}\nAvailable assets: {}",
                    asset_name,
                    Self::format_asset_list(available_assets.iter())
                )
            })?;

        // Try to get checksum from API digest or fetch from release assets
        let digest = if asset.digest.is_some() {
            asset.digest.clone()
        } else {
            self.try_fetch_checksum_from_assets(&assets_with_urls, &asset.name)
                .await
        };

        Ok(ReleaseAsset {
            name: asset.name.clone(),
            url: asset.browser_download_url.clone(),
            url_api: asset.url.clone(),
            digest,
        })
    }

//! Unified asset matching for backend tool installation
//!
//! This module provides a high-level `AssetMatcher` that uses platform heuristics
//! to score and rank assets for finding the best download for the target platform.
//!
//! # Example
//!
//! ```ignore
//! use crate::backend::asset_matcher::AssetMatcher;
//!
//! // Auto-detect best asset for a target platform
//! let asset = AssetMatcher::new()
//!     .for_target(&target)
//!     .with_no_app(true) // optional: avoid .app bundles
//!     .pick_from(&assets)?;
//! ```

use eyre::Result;
use regex::Regex;
use std::sync::LazyLock;

use super::platform_target::PlatformTarget;
use super::platform_tokens::is_platform_or_version_token;
use super::static_helpers::get_filename_from_url;
use crate::file::ExtractionFormat;
use crate::http::HTTP;

// ========== Platform Detection Types (from asset_detector) ==========

#[derive(Debug, Clone, Copy, PartialEq)]
pub(crate) enum AssetOs {
    Linux,
    Macos,
    Windows,
    Android,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub(crate) enum AssetArch {
    X64,
    Arm64,
    X86,
    Arm,
    Riscv64,
    Loongarch64,
}

#[derive(Debug, Clone, Copy, PartialEq)]
pub(crate) enum AssetLibc {
    Gnu,
    Musl,
    Msvc,
}

impl AssetOs {
    pub(crate) fn matches_target(&self, target: &str) -> bool {
        match self {
            AssetOs::Linux => target == "linux",
            AssetOs::Macos => target == "macos" || target == "darwin",
            AssetOs::Windows => target == "windows",
            AssetOs::Android => target == "android",
        }
    }
}

impl AssetArch {
    pub(crate) fn matches_target(&self, target: &str) -> bool {
        match self {
            AssetArch::X64 => target == "x86_64" || target == "amd64" || target == "x64",
            AssetArch::Arm64 => target == "aarch64" || target == "arm64",
            AssetArch::X86 => target == "x86" || target == "i386" || target == "i686",
            AssetArch::Arm => target == "arm",
            AssetArch::Riscv64 => target == "riscv64" || target == "riscv64gc",
            AssetArch::Loongarch64 => target == "loongarch64" || target == "loong64",
        }
    }
}

impl AssetLibc {
    pub(crate) fn matches_target(&self, target: &str) -> bool {
        target.split('-').any(|part| match self {
            AssetLibc::Gnu => part == "gnu" || part == "glibc",
            AssetLibc::Musl => part == "musl",
            AssetLibc::Msvc => part == "msvc",
        })
    }
}

/// Detected platform information from a URL
#[derive(Debug, Clone)]
pub(crate) struct DetectedPlatform {
    pub os: AssetOs,
    pub arch: AssetArch,
    #[allow(unused)]
    pub libc: Option<AssetLibc>,
}

impl DetectedPlatform {
    /// Convert to mise's platform string format (e.g., "linux-x64", "macos-arm64")
    pub(crate) fn to_platform_string(&self) -> String {
        let os_str = match self.os {
            AssetOs::Linux => "linux",
            AssetOs::Macos => "macos",
            AssetOs::Windows => "windows",
            AssetOs::Android => "android",
        };

        let arch_str = match self.arch {
            AssetArch::X64 => "x64",
            AssetArch::Arm64 => "arm64",
            AssetArch::X86 => "x86",
            AssetArch::Arm => "arm",
            AssetArch::Riscv64 => "riscv64",
            AssetArch::Loongarch64 => "loongarch64",
        };

        format!("{os_str}-{arch_str}")
    }
}

